  var HTMLMAP = {"#menuEv":{"tr":"Elektrikli Araç Dönüşümü","de":"E-Fahrzeug-Umbau"},"#heroTitle":{"tr":"Güneşten <span class=\"hl\">kazanca</span> dönüşen enerji.","de":"Energie, die aus Sonne <span class=\"hl\">Gewinn</span> macht."},"#calcLead":{"tr":"Sadece faturanızı girin; <strong>sistem gücü, yıllık tasarruf, geri ödeme süresi ve 25 yıllık kazancınızı</strong> saniyeler içinde görün. Üstelik panel yerleşimi, inverter ve kablo gibi <strong>mühendislik araçları</strong> da burada.","de":"Geben Sie einfach Ihre Rechnung ein und sehen Sie <strong>Anlagengröße, jährliche Ersparnis, Amortisationszeit und Ihren 25-Jahres-Ertrag</strong> in Sekunden. Dazu <strong>Engineering-Tools</strong> für Modulbelegung, Wechselrichter und Kabel."},"#shopNoJs":{"tr":"Ürünleri görüntülemek için JavaScript'i etkinleştirin veya <a href=\"iletisim.html\">bizimle iletişime geçin</a>.","de":"Aktivieren Sie JavaScript, um die Produkte zu sehen, oder <a href=\"iletisim.html\">kontaktieren Sie uns</a>."},"#ordConsent":{"tr":"Siparişi göndererek <a href=\"/kvkk.html\">KVKK Aydınlatma Metni</a>'ni ve aşağıdaki satış şartlarını kabul etmiş olursunuz.","de":"Mit dem Absenden der Bestellung akzeptieren Sie die <a href=\"/kvkk.html\">Datenschutzerklärung (KVKK)</a> und die unten stehenden Verkaufsbedingungen."}};
